   <label>\u9AD8\u3055\u306E\u56FA\u5B9A\u4F4D\u7F6E<select id="form-size-anchor"><option value="center">\u4E2D\u592E</option><option value="bottom">\u4E0B\u7AEF</option><option value="top">\u4E0A\u7AEF</option></select></label>
